function formatDirLabel(a) {
  if (a.name === 'copilot') {
    return './.github/skills/ or ~/.copilot/skills/'
  }
  if (DUAL_PATH_AGENTS.has(a.name)) {
    const homePath = a.label
    const projName = NAME_TO_DIR[a.name] || a.name
    const projPath = `./.${projName}/skills/`
    return `${homePath} or ${projPath}`
  }
  return a.label
}
